// src/services/taskService.js
import api from "./api";

const taskService = {
  // Get all tasks with cognitive load
  getTasks: () => api.get("/tasks"),

  // Create task with AI analysis
  createTask: (taskData) => api.post("/tasks", taskData),

  // Update task
  updateTask: (taskId, updates) => api.put(`/tasks/${taskId}`, updates),

  // Complete task with proof
  completeTask: (taskId, proofFile) => {
    const formData = new FormData();
    if (proofFile) {
      formData.append("proof", proofFile);
    }
    return api.post(`/tasks/${taskId}/complete`, formData, {
      headers: { "Content-Type": "multipart/form-data" },
    });
  },

  // Delete task
  deleteTask: (taskId) => api.delete(`/tasks/${taskId}`),

  // Get failure predictions
  getFailurePredictions: () => api.get("/tasks/predictions"),

  // Get cognitive load
  getCognitiveLoad: () => api.get("/tasks/cognitive-load"),

  // Get impact simulation for a task
  getImpactSimulation: (taskId) => api.get(`/tasks/${taskId}/impact`),

  // Update subtask
  updateSubtask: (taskId, subtaskId, completed) =>
    api.put(`/tasks/${taskId}/subtasks/${subtaskId}`, { completed }),

  // AI endpoints
  classifyRisk: (taskData) => api.post("/ai/classify-risk", taskData),
  generateSubtasks: (taskData) => api.post("/ai/generate-subtasks", taskData),
  predictFailure: (taskData) => api.post("/ai/predict-failure", taskData),
  simulateImpact: (taskData) => api.post("/ai/simulate-impact", taskData),
  analyzeCompletion: (taskData) => api.post("/ai/analyze-completion", taskData),
  getTaskAdvice: (taskData) => api.post("/ai/get-advice", taskData),
};

export default taskService;
