// src/context/AuthContext.js
import React, { createContext, useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import authService from "../services/authService";

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [availableAccounts, setAvailableAccounts] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const token = localStorage.getItem("token");
    const userData = localStorage.getItem("user");

    if (token && userData) {
      try {
        const parsedUser = JSON.parse(userData);
        setUser(parsedUser);
        loadAvailableAccounts();
      } catch (e) {
        console.error("Error parsing user data:", e);
        localStorage.removeItem("token");
        localStorage.removeItem("user");
      }
    }
    setLoading(false);
  }, []);

  const loadAvailableAccounts = async () => {
    try {
      const { default: dashboardService } = await import(
        "../services/dashboardService"
      );
      const response = await dashboardService.getLinkedAccounts();
      setAvailableAccounts(response.data || []);
    } catch (error) {
      console.error("Error loading linked accounts:", error);
    }
  };

  const login = async (email, password) => {
    try {
      const response = await authService.login(email, password);
      const { token, user: userData } = response.data;

      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(userData));
      setUser(userData);

      toast.success(`Welcome back, ${userData.name}!`);

      // Load available accounts after login
      await loadAvailableAccounts();

      // Navigating directly to dashboard as requested (ContextSetup was removed)
      navigate("/dashboard");

      return { success: true };
    } catch (error) {
      const message =
        error.response?.data?.message || "Login failed. Please try again.";
      toast.error(message);
      return { success: false, error: message };
    }
  };

  const register = async (name, email, password) => {
    try {
      const response = await authService.register(name, email, password);
      toast.success("Registration successful! Please login.");
      navigate("/login");
      return { success: true };
    } catch (error) {
      const message =
        error.response?.data?.message ||
        "Registration failed. Please try again.";
      toast.error(message);
      return { success: false, error: message };
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    setUser(null);
    setAvailableAccounts([]);
    toast.success("Logged out successfully");
    navigate("/login");
  };

  const updateUser = (updates) => {
    const updatedUser = { ...user, ...updates };
    setUser(updatedUser);
    localStorage.setItem("user", JSON.stringify(updatedUser));
  };

  const switchAccount = async (accountId) => {
    try {
      const { default: dashboardService } = await import(
        "../services/dashboardService"
      );
      await dashboardService.switchAccount(accountId);
      toast.success("Account switched successfully");
      // In a real app, this might return a new token or update user data
      // For now, we'll just reload the accounts and user info if needed
      await loadAvailableAccounts();
      return { success: true };
    } catch (error) {
      toast.error("Failed to switch account");
      return { success: false };
    }
  };

  const updateUserStats = (stats) => {
    // This could be used to update local user state with new stats/xp/level
    setUser((prev) => ({
      ...prev,
      stats: { ...prev?.stats, ...stats },
    }));
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        availableAccounts,
        login,
        register,
        logout,
        updateUser,
        switchAccount,
        updateUserStats,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};
