// src/pages/Dashboard.jsx
import React, {
  useState,
  useEffect,
  useContext,
  useCallback,
  useMemo,
  useRef,
} from "react";
import { useNavigate } from "react-router-dom";
import {
  Container,
  Row,
  Col,
  Card,
  Button,
  Badge,
  ProgressBar,
  ListGroup,
  Spinner,
  Form,
  InputGroup,
  Dropdown,
  Modal,
  ToastContainer,
  Navbar,
  Nav,
  Image,
  OverlayTrigger,
  Tooltip,
} from "react-bootstrap";
import {
  Plus,
  Upload,
  AlertTriangle,
  CheckCircle,
  Clock,
  Calendar,
  Search,
  X,
  Bell,
  Shield,
  Brain,
  BarChart3,
  Eye,
  Sparkles,
  Zap,
  AlertOctagon,
  LogOut,
  Users,
  Settings,
  User,
  Moon,
  Sun,
  Activity,
  Award,
  Star,
  Gift,
} from "lucide-react";
import { TaskContext } from "../context/TaskContext";
import { AuthContext } from "../context/AuthContext";
import dashboardService from "../services/dashboardService";
import ImpactSimulationModal from "../components/tasks/ImpactSimulationModal";
import CognitiveLoadWarning from "../components/dashboard/CognitiveLoadWarning";
import AccountSwitcher from "../components/dashboard/AccountSwitcher";
import QuickActions from "../components/dashboard/QuickActions";
import AchievementBadge from "../components/dashboard/AchievementBadge";

const Dashboard = () => {
  const navigate = useNavigate();
  const {
    tasks,
    stats,
    loading,
    getTodayTasks,
    getHighRiskTasks,
    getUpcomingTasks,
    getOverdueTasks,
    completeTask,
    cognitiveLoad,
    failurePredictions,
    loadFailurePredictions,
  } = useContext(TaskContext);

  const { user, logout, switchAccount, availableAccounts, updateUserStats } =
    useContext(AuthContext);

  const [searchTerm, setSearchTerm] = useState("");
  const [filterType, setFilterType] = useState("ALL");
  const [sortBy, setSortBy] = useState("dueDate");
  const [sortOrder, setSortOrder] = useState("asc");
  const [viewMode, setViewMode] = useState("list");
  const [selectedTask, setSelectedTask] = useState(null);
  const [showImpactModal, setShowImpactModal] = useState(false);
  const [showCompleteModal, setShowCompleteModal] = useState(false);
  const [taskToComplete, setTaskToComplete] = useState(null);
  const [completionProof, setCompletionProof] = useState(null);
  const [dashboardAnalytics, setDashboardAnalytics] = useState(null);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [todayTasks, setTodayTasks] = useState([]);
  const [highRiskTasks, setHighRiskTasks] = useState([]);
  const [upcomingTasks, setUpcomingTasks] = useState([]);
  const [overdueTasks, setOverdueTasks] = useState([]);
  const [filteredTasks, setFilteredTasks] = useState([]);
  const [weeklyTrend, setWeeklyTrend] = useState([]);
  const [attentionTasks, setAttentionTasks] = useState([]);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [showAccountSwitcher, setShowAccountSwitcher] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [darkMode, setDarkMode] = useState(
    localStorage.getItem("darkMode") === "true",
  );
  const [showQuickActions, setShowQuickActions] = useState(false);
  const [userStats, setUserStats] = useState({
    streak: 0,
    achievements: [],
    level: 1,
    xp: 0,
    nextLevelXp: 1000,
  });
  const [showAchievementModal, setShowAchievementModal] = useState(false);
  const [newAchievement, setNewAchievement] = useState(null);

  const notificationRef = useRef(null);
  const accountSwitcherRef = useRef(null);

  // Apply dark mode
  useEffect(() => {
    if (darkMode) {
      document.body.classList.add("dark-mode");
      localStorage.setItem("darkMode", "true");
    } else {
      document.body.classList.remove("dark-mode");
      localStorage.setItem("darkMode", "false");
    }
  }, [darkMode]);

  // Load user stats and achievements
  useEffect(() => {
    loadUserStats();
    loadNotifications();
  }, [user]);

  const loadUserStats = async () => {
    try {
      const response = await dashboardService.getUserStats();
      setUserStats(response.data);
      if (updateUserStats) {
        updateUserStats(response.data);
      }
    } catch (error) {
      console.error("Error loading user stats:", error);
    }
  };

  const loadNotifications = async () => {
    try {
      const response = await dashboardService.getNotifications();
      setNotifications(response.data || []);
    } catch (error) {
      console.error("Error loading notifications:", error);
    }
  };

  useEffect(() => {
    if (!loading) {
      setTodayTasks(getTodayTasks());
      setHighRiskTasks(getHighRiskTasks());
      setUpcomingTasks(getUpcomingTasks(7));
      setOverdueTasks(getOverdueTasks());
      loadDashboardData();
      if (loadFailurePredictions) {
        loadFailurePredictions();
      }
    }
  }, [tasks, loading]);

  const loadDashboardData = async () => {
    try {
      const response = await dashboardService.getSummary();
      setDashboardAnalytics(response.data);
      setAttentionTasks(response.data.attentionTasks || []);
      setWeeklyTrend(response.data.weeklyTrend || []);
    } catch (error) {
      console.error("Error loading dashboard data:", error);
    }
  };

  const getTasksByFilter = useCallback(() => {
    let tasksToFilter = [];

    switch (filterType) {
      case "TODAY":
        tasksToFilter = [...todayTasks];
        break;
      case "UPCOMING":
        tasksToFilter = [...upcomingTasks];
        break;
      case "OVERDUE":
        tasksToFilter = [...overdueTasks];
        break;
      case "HIGH_RISK":
        tasksToFilter = [...highRiskTasks];
        break;
      case "COMPLETED":
        tasksToFilter = tasks.filter((t) => t.status === "COMPLETED");
        break;
      default:
        tasksToFilter = tasks.filter((t) => t.status === "ACTIVE");
        break;
    }

    if (searchTerm.trim()) {
      const term = searchTerm.toLowerCase();
      tasksToFilter = tasksToFilter.filter(
        (task) =>
          task.title.toLowerCase().includes(term) ||
          (task.description && task.description.toLowerCase().includes(term)) ||
          (task.tags &&
            task.tags.some((tag) => tag.toLowerCase().includes(term))),
      );
    }

    tasksToFilter.sort((a, b) => {
      let comparison = 0;
      switch (sortBy) {
        case "dueDate":
          comparison = new Date(a.dueDate) - new Date(b.dueDate);
          break;
        case "riskScore":
          const riskA = a.riskAnalysis?.riskScore || 0;
          const riskB = b.riskAnalysis?.riskScore || 0;
          comparison = riskA - riskB;
          break;
        case "priority":
          const priorityWeight = { HIGH: 3, MEDIUM: 2, LOW: 1 };
          comparison =
            (priorityWeight[a.priority] || 0) -
            (priorityWeight[b.priority] || 0);
          break;
        default:
          comparison = 0;
      }
      return sortOrder === "asc" ? comparison : -comparison;
    });

    return tasksToFilter;
  }, [
    filterType,
    todayTasks,
    upcomingTasks,
    overdueTasks,
    highRiskTasks,
    tasks,
    searchTerm,
    sortBy,
    sortOrder,
  ]);

  useEffect(() => {
    setFilteredTasks(getTasksByFilter());
  }, [getTasksByFilter]);

  const getFilterCount = (type) => {
    switch (type) {
      case "ALL":
        return tasks.filter((t) => t.status === "ACTIVE").length;
      case "TODAY":
        return todayTasks.length;
      case "UPCOMING":
        return upcomingTasks.length;
      case "OVERDUE":
        return overdueTasks.length;
      case "HIGH_RISK":
        return highRiskTasks.length;
      case "COMPLETED":
        return tasks.filter((t) => t.status === "COMPLETED").length;
      default:
        return 0;
    }
  };

  const completionRate =
    tasks.length > 0 ? Math.round((stats.completed / tasks.length) * 100) : 0;
  const onTimeRate = useMemo(() => {
    const completedTasks = tasks.filter((t) => t.status === "COMPLETED");
    if (completedTasks.length === 0) return 0;
    const onTime = completedTasks.filter((t) => {
      if (t.completedAt && t.dueDate) {
        return new Date(t.completedAt) <= new Date(t.dueDate);
      }
      return false;
    });
    return Math.round((onTime.length / completedTasks.length) * 100);
  }, [tasks]);

  const avgRiskScore = useMemo(() => {
    const activeTasks = tasks.filter((t) => t.status === "ACTIVE");
    if (activeTasks.length === 0) return 0;
    const totalRisk = activeTasks.reduce(
      (sum, t) => sum + (t.riskAnalysis?.riskScore || 0),
      0,
    );
    return Math.round(totalRisk / activeTasks.length);
  }, [tasks]);

  const handleCompleteTask = async () => {
    if (!taskToComplete) return;
    try {
      await completeTask(taskToComplete.id, completionProof);
      setShowCompleteModal(false);
      setTaskToComplete(null);
      setCompletionProof(null);

      // Check for achievement
      try {
        const achievement =
          await dashboardService.checkAchievement("task_complete");
        if (achievement.data && achievement.data.id) {
          setNewAchievement(achievement.data);
          setShowAchievementModal(true);
        }
      } catch (error) {
        console.error("Error checking achievement:", error);
      }
    } catch (error) {
      console.error("Error completing task:", error);
    }
  };

  const handleViewImpact = (task) => {
    setSelectedTask(task);
    setShowImpactModal(true);
  };

  const handleLogout = async () => {
    try {
      if (logout) {
        await logout();
      }
      navigate("/login");
    } catch (error) {
      console.error("Error logging out:", error);
    }
  };

  const handleSwitchAccount = async (accountId) => {
    try {
      if (switchAccount) {
        await switchAccount(accountId);
      }
      setShowAccountSwitcher(false);
      // Reload dashboard data for new account
      loadDashboardData();
      loadUserStats();
    } catch (error) {
      console.error("Error switching account:", error);
    }
  };

  const markNotificationRead = async (notificationId) => {
    try {
      await dashboardService.markNotificationRead(notificationId);
      setNotifications(
        notifications.map((n) =>
          n.id === notificationId ? { ...n, read: true } : n,
        ),
      );
    } catch (error) {
      console.error("Error marking notification read:", error);
    }
  };

  const getRiskBadge = (riskLevel, riskScore) => {
    const config = {
      CRITICAL: { bg: "danger", icon: AlertTriangle, text: "Critical" },
      WARNING: { bg: "warning", icon: AlertTriangle, text: "Warning" },
      SAFE: { bg: "success", icon: Shield, text: "Safe" },
    };
    const { bg, icon: Icon, text } = config[riskLevel] || config.SAFE;
    return (
      <Badge bg={bg} pill className="d-flex align-items-center gap-1 px-2 py-1">
        <Icon size={12} />
        <span>{text}</span>
        {riskScore && <span className="ms-1">({riskScore}%)</span>}
      </Badge>
    );
  };

  const getPriorityBadge = (priority) => {
    const config = {
      HIGH: { bg: "danger", text: "High Priority" },
      MEDIUM: { bg: "warning", text: "Medium Priority" },
      LOW: { bg: "success", text: "Low Priority" },
    };
    const { bg, text } = config[priority] || config.LOW;
    return (
      <Badge bg={bg} pill className="px-2 py-1">
        {text}
      </Badge>
    );
  };

  const getCategoryIcon = (category) => {
    const icons = {
      ACADEMIC: "📚",
      OPPORTUNITY: "💼",
      PERSONAL_GOAL: "🎯",
      EVENT: "📅",
    };
    return icons[category] || "📌";
  };

  const formatDate = (date) => {
    return new Date(date).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const getDaysRemaining = (dueDate) => {
    const days = Math.ceil(
      (new Date(dueDate) - new Date()) / (1000 * 60 * 60 * 24),
    );
    if (days < 0) return `${Math.abs(days)} days overdue`;
    if (days === 0) return "Due today";
    return `${days} days left`;
  };

  // Click outside handlers
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (
        notificationRef.current &&
        !notificationRef.current.contains(event.target)
      ) {
        setShowNotifications(false);
      }
      if (
        accountSwitcherRef.current &&
        !accountSwitcherRef.current.contains(event.target)
      ) {
        setShowAccountSwitcher(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  if (loading) {
    return (
      <Container className="text-center py-5">
        <div>
          <Spinner animation="border" variant="primary" size="lg" />
          <p className="mt-3 text-muted">Loading your dashboard...</p>
        </div>
      </Container>
    );
  }

  return (
    <>
      {/* Modern Navbar */}
      <Navbar
        bg={darkMode ? "dark" : "light"}
        variant={darkMode ? "dark" : "light"}
        className="shadow-sm sticky-top"
      >
        <Container fluid>
          <Navbar.Brand href="#" className="d-flex align-items-center gap-2">
            <Brain size={28} className="text-primary" />
            <span className="fw-bold">TaskFlow AI</span>
            <Badge bg="info" className="ms-2">
              Beta
            </Badge>
          </Navbar.Brand>

          <Nav className="ms-auto align-items-center gap-3">
            {/* Quick Actions Toggle */}
            <OverlayTrigger
              placement="bottom"
              overlay={<Tooltip>Quick Actions</Tooltip>}
            >
              <Button
                variant="outline-primary"
                size="sm"
                onClick={() => setShowQuickActions(!showQuickActions)}
                className="position-relative"
              >
                <Zap size={18} />
                {cognitiveLoad?.isOverloaded && (
                  <span className="position-absolute top-0 start-100 translate-middle p-1 bg-danger border border-light rounded-circle">
                    <span className="visually-hidden">Alerts</span>
                  </span>
                )}
              </Button>
            </OverlayTrigger>

            {/* Notifications */}
            <OverlayTrigger
              placement="bottom"
              overlay={<Tooltip>Notifications</Tooltip>}
            >
              <div ref={notificationRef} className="position-relative">
                <Button
                  variant="outline-secondary"
                  size="sm"
                  onClick={() => setShowNotifications(!showNotifications)}
                >
                  <Bell size={18} />
                  {notifications.filter((n) => !n.read).length > 0 && (
                    <Badge
                      bg="danger"
                      pill
                      className="position-absolute top-0 start-100 translate-middle"
                    >
                      {notifications.filter((n) => !n.read).length}
                    </Badge>
                  )}
                </Button>

                {/* Notifications Dropdown */}
                {showNotifications && (
                  <div
                    className="position-absolute end-0 mt-2"
                    style={{ width: "320px", zIndex: 1050 }}
                  >
                    <Card className="shadow-lg">
                      <Card.Header className="d-flex justify-content-between align-items-center">
                        <span className="fw-semibold">Notifications</span>
                        <Button
                          variant="link"
                          size="sm"
                          onClick={() => setShowNotifications(false)}
                          className="p-0"
                        >
                          <X size={14} />
                        </Button>
                      </Card.Header>
                      <Card.Body
                        className="p-0"
                        style={{ maxHeight: "400px", overflowY: "auto" }}
                      >
                        {notifications.length > 0 ? (
                          notifications.map((notification) => (
                            <div
                              key={notification.id}
                              className={`p-3 border-bottom ${!notification.read ? "bg-light" : ""}`}
                              onClick={() =>
                                markNotificationRead(notification.id)
                              }
                              style={{ cursor: "pointer" }}
                            >
                              <div className="d-flex gap-2">
                                <div className="flex-shrink-0">
                                  {notification.type === "task" && (
                                    <CheckCircle
                                      size={16}
                                      className="text-success"
                                    />
                                  )}
                                  {notification.type === "alert" && (
                                    <AlertTriangle
                                      size={16}
                                      className="text-danger"
                                    />
                                  )}
                                  {notification.type === "achievement" && (
                                    <Award size={16} className="text-warning" />
                                  )}
                                </div>
                                <div>
                                  <p className="mb-1 small">
                                    {notification.message}
                                  </p>
                                  <small className="text-muted">
                                    {new Date(
                                      notification.createdAt,
                                    ).toLocaleDateString()}
                                  </small>
                                </div>
                              </div>
                            </div>
                          ))
                        ) : (
                          <div className="text-center py-4">
                            <Bell size={32} className="text-muted mb-2" />
                            <p className="text-muted mb-0">No notifications</p>
                          </div>
                        )}
                      </Card.Body>
                    </Card>
                  </div>
                )}
              </div>
            </OverlayTrigger>

            {/* Dark Mode Toggle */}
            <OverlayTrigger
              placement="bottom"
              overlay={
                <Tooltip>{darkMode ? "Light Mode" : "Dark Mode"}</Tooltip>
              }
            >
              <Button
                variant="outline-secondary"
                size="sm"
                onClick={() => setDarkMode(!darkMode)}
              >
                {darkMode ? <Sun size={18} /> : <Moon size={18} />}
              </Button>
            </OverlayTrigger>

            {/* User Menu */}
            <div ref={accountSwitcherRef}>
              <Dropdown align="end">
                <Dropdown.Toggle
                  variant="outline-secondary"
                  id="user-dropdown"
                  className="d-flex align-items-center gap-2"
                >
                  <div className="position-relative">
                    <Image
                      src={
                        user?.avatar ||
                        `https://ui-avatars.com/api/?name=${user?.name}&background=0D6EFD&color=fff`
                      }
                      roundedCircle
                      width="32"
                      height="32"
                    />
                    {userStats.streak > 0 && (
                      <div className="position-absolute bottom-0 end-0 bg-success rounded-circle p-1 border border-white">
                        <Star size={8} fill="white" />
                      </div>
                    )}
                  </div>
                  <span className="d-none d-md-inline">{user?.name}</span>
                </Dropdown.Toggle>

                <Dropdown.Menu>
                  <Dropdown.Item onClick={() => navigate("/profile")}>
                    <User size={16} className="me-2" /> Profile
                  </Dropdown.Item>
                  <Dropdown.Item onClick={() => setShowAccountSwitcher(true)}>
                    <Users size={16} className="me-2" /> Switch Account
                  </Dropdown.Item>
                  <Dropdown.Item onClick={() => navigate("/settings")}>
                    <Settings size={16} className="me-2" /> Settings
                  </Dropdown.Item>
                  <Dropdown.Divider />
                  <Dropdown.Item
                    onClick={() => setShowLogoutConfirm(true)}
                    className="text-danger"
                  >
                    <LogOut size={16} className="me-2" /> Logout
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>
          </Nav>
        </Container>
      </Navbar>

      {/* Quick Actions Sidebar */}
      {showQuickActions && (
        <div
          className="position-fixed start-0 top-0 h-100 bg-white shadow-lg"
          style={{ width: "300px", zIndex: 1040, marginTop: "56px" }}
        >
          <QuickActions onClose={() => setShowQuickActions(false)} />
        </div>
      )}

      <Container fluid className="py-4 px-4">
        {/* Header with User Stats */}
        <Row className="mb-4 align-items-center">
          <Col md={8}>
            <div>
              <h2 className="text-primary mb-1 fw-bold">
                Welcome back, {user?.name || "User"}! 👋
              </h2>
              <p className="text-muted mb-0">
                {new Date().toLocaleDateString("en-US", {
                  weekday: "long",
                  year: "numeric",
                  month: "long",
                  day: "numeric",
                })}
              </p>
            </div>
          </Col>
          <Col md={4}>
            <div className="d-flex gap-2 justify-content-end">
              <Button
                variant="outline-primary"
                onClick={() => navigate("/create-task")}
              >
                <Plus size={18} className="me-2" />
                Manual Add
              </Button>
              <Button
                variant="primary"
                onClick={() => navigate("/create-task?smart=true")}
              >
                <Sparkles size={18} className="me-2" />
                Smart Intake
              </Button>
            </div>
          </Col>
        </Row>

        {/* User Stats Bar */}
        <Row className="mb-4">
          <Col>
            <Card className="shadow-sm border-0 bg-gradient-primary text-white">
              <Card.Body>
                <div className="d-flex justify-content-between align-items-center flex-wrap gap-3">
                  <div className="d-flex align-items-center gap-3">
                    <div className="bg-white bg-opacity-25 p-3 rounded-circle">
                      <Activity size={24} className="text-white" />
                    </div>
                    <div>
                      <small className="text-white-50">
                        Level {userStats.level}
                      </small>
                      <h5 className="text-white mb-0">
                        {userStats.xp} / {userStats.nextLevelXp} XP
                      </h5>
                      <ProgressBar
                        now={(userStats.xp / userStats.nextLevelXp) * 100}
                        variant="light"
                        className="mt-1"
                        style={{ height: "4px", width: "200px" }}
                      />
                    </div>
                  </div>
                  <div className="d-flex align-items-center gap-3">
                    <div className="text-center">
                      <Award size={20} className="text-white mb-1" />
                      <div className="text-white">
                        <strong>{userStats.achievements?.length || 0}</strong>
                        <small className="d-block text-white-50">
                          Achievements
                        </small>
                      </div>
                    </div>
                    <div className="text-center">
                      <Star size={20} className="text-warning mb-1" />
                      <div className="text-white">
                        <strong>{userStats.streak}</strong>
                        <small className="d-block text-white-50">
                          Day Streak
                        </small>
                      </div>
                    </div>
                    <div className="text-center">
                      <Gift size={20} className="text-white mb-1" />
                      <div className="text-white">
                        <strong>{(userStats.xp / 100).toFixed(1)}</strong>
                        <small className="d-block text-white-50">Coins</small>
                      </div>
                    </div>
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>

        {/* Cognitive Load Warning */}
        {cognitiveLoad?.isOverloaded && (
          <Row className="mb-4">
            <Col>
              <CognitiveLoadWarning
                activeCount={cognitiveLoad.activeTasksCount}
                warningMessage={cognitiveLoad.warningMessage}
                maxCapacity={cognitiveLoad.maxCapacity}
              />
            </Col>
          </Row>
        )}

        {/* Stats Cards */}
        <Row className="mb-4 g-3">
          <Col md={3}>
            <div className="card-hover">
              <Card className="shadow-sm border-0 h-100 bg-primary text-white">
                <Card.Body>
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <p className="text-white-50 mb-1">Total Tasks</p>
                      <h2 className="text-white mb-0 fw-bold">
                        {tasks.length}
                      </h2>
                      <small className="text-white-50">
                        {stats.active} active · {stats.completed} completed
                      </small>
                    </div>
                    <div className="bg-white-20 p-3 rounded-circle">
                      <Calendar size={28} className="text-white" />
                    </div>
                  </div>
                </Card.Body>
              </Card>
            </div>
          </Col>
          <Col md={3}>
            <div className="card-hover">
              <Card className="shadow-sm border-0 h-100 bg-success text-white">
                <Card.Body>
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <p className="text-white-50 mb-1">Completion Rate</p>
                      <h2 className="text-white mb-0 fw-bold">
                        {completionRate}%
                      </h2>
                      <small className="text-white-50">
                        {stats.completed} / {tasks.length} tasks
                      </small>
                    </div>
                    <div className="bg-white-20 p-3 rounded-circle">
                      <CheckCircle size={28} className="text-white" />
                    </div>
                  </div>
                  <ProgressBar
                    now={completionRate}
                    variant="light"
                    className="mt-3"
                    style={{ height: "6px" }}
                  />
                </Card.Body>
              </Card>
            </div>
          </Col>
          <Col md={3}>
            <div className="card-hover">
              <Card className="shadow-sm border-0 h-100 bg-warning text-white">
                <Card.Body>
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <p className="text-white-50 mb-1">On-Time Rate</p>
                      <h2 className="text-white mb-0 fw-bold">{onTimeRate}%</h2>
                      <small className="text-white-50">
                        Completed before deadline
                      </small>
                    </div>
                    <div className="bg-white-20 p-3 rounded-circle">
                      <Clock size={28} className="text-white" />
                    </div>
                  </div>
                </Card.Body>
              </Card>
            </div>
          </Col>
          <Col md={3}>
            <div className="card-hover">
              <Card className="shadow-sm border-0 h-100 bg-info text-white">
                <Card.Body>
                  <div className="d-flex justify-content-between align-items-start">
                    <div>
                      <p className="text-white-50 mb-1">Avg Risk Score</p>
                      <h2 className="text-white mb-0 fw-bold">
                        {avgRiskScore}%
                      </h2>
                      <small className="text-white-50">
                        {highRiskTasks.length} high risk tasks
                      </small>
                    </div>
                    <div className="bg-white-20 p-3 rounded-circle">
                      <Shield size={28} className="text-white" />
                    </div>
                  </div>
                </Card.Body>
              </Card>
            </div>
          </Col>
        </Row>

        {/* Search and Filters */}
        <Row className="mb-4">
          <Col md={5}>
            <InputGroup>
              <InputGroup.Text className="bg-white border-end-0">
                <Search size={18} className="text-muted" />
              </InputGroup.Text>
              <Form.Control
                type="text"
                placeholder="Search tasks..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="border-start-0"
              />
              {searchTerm && (
                <Button
                  variant="outline-secondary"
                  onClick={() => setSearchTerm("")}
                >
                  <X size={18} />
                </Button>
              )}
            </InputGroup>
          </Col>
          <Col md={4}>
            <div className="d-flex gap-2">
              <Dropdown>
                <Dropdown.Toggle variant="outline-secondary" size="sm">
                  <BarChart3 size={14} className="me-1" />
                  Sort:{" "}
                  {sortBy === "dueDate"
                    ? "Due Date"
                    : sortBy === "riskScore"
                      ? "Risk"
                      : "Priority"}
                </Dropdown.Toggle>
                <Dropdown.Menu>
                  <Dropdown.Item onClick={() => setSortBy("dueDate")}>
                    Due Date
                  </Dropdown.Item>
                  <Dropdown.Item onClick={() => setSortBy("riskScore")}>
                    Risk Score
                  </Dropdown.Item>
                  <Dropdown.Item onClick={() => setSortBy("priority")}>
                    Priority
                  </Dropdown.Item>
                  <Dropdown.Divider />
                  <Dropdown.Item
                    onClick={() =>
                      setSortOrder(sortOrder === "asc" ? "desc" : "asc")
                    }
                  >
                    Toggle Order (
                    {sortOrder === "asc" ? "Ascending" : "Descending"})
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>
          </Col>
          <Col md={3}>
            <div className="d-flex gap-2 justify-content-end flex-wrap">
              {[
                "ALL",
                "TODAY",
                "UPCOMING",
                "OVERDUE",
                "HIGH_RISK",
                "COMPLETED",
              ].map((type) => (
                <Button
                  key={type}
                  variant={filterType === type ? "primary" : "outline-primary"}
                  size="sm"
                  onClick={() => setFilterType(type)}
                >
                  {type === "ALL" && "All Active"}
                  {type === "TODAY" && `Today (${getFilterCount("TODAY")})`}
                  {type === "UPCOMING" &&
                    `Upcoming (${getFilterCount("UPCOMING")})`}
                  {type === "OVERDUE" &&
                    `Overdue (${getFilterCount("OVERDUE")})`}
                  {type === "HIGH_RISK" &&
                    `High Risk (${getFilterCount("HIGH_RISK")})`}
                  {type === "COMPLETED" &&
                    `Completed (${getFilterCount("COMPLETED")})`}
                </Button>
              ))}
            </div>
          </Col>
        </Row>

        {/* Main Content */}
        <Row>
          {/* Left Column - Intelligence Cards */}
          <Col lg={4}>
            {/* Failure Predictions */}
            {failurePredictions && failurePredictions.length > 0 && (
              <Card className="shadow-sm mb-4 border-0">
                <Card.Header className="bg-danger text-white">
                  <div className="d-flex align-items-center gap-2">
                    <Brain size={18} />
                    <h6 className="mb-0 fw-semibold">AI Failure Predictions</h6>
                  </div>
                </Card.Header>
                <Card.Body className="p-0">
                  {failurePredictions.slice(0, 3).map((pred) => (
                    <div
                      key={pred.taskId}
                      className="p-3 border-bottom cursor-pointer"
                      onClick={() => navigate(`/task/${pred.taskId}`)}
                    >
                      <div className="d-flex justify-content-between align-items-start mb-2">
                        <h6 className="mb-0 fw-semibold">{pred.title}</h6>
                        <Badge
                          bg={pred.probability > 70 ? "danger" : "warning"}
                          pill
                        >
                          {pred.probability}%
                        </Badge>
                      </div>
                      <p className="small text-muted mb-2">{pred.reason}</p>
                      <div className="d-flex justify-content-between">
                        <small className="text-primary">
                          {pred.recommendedAction}
                        </small>
                        <Button
                          variant="link"
                          size="sm"
                          className="p-0"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleViewImpact(
                              tasks.find((t) => t.id === pred.taskId),
                            );
                          }}
                        >
                          View Impact →
                        </Button>
                      </div>
                    </div>
                  ))}
                </Card.Body>
              </Card>
            )}

            {/* High Risk Alerts */}
            {highRiskTasks.length > 0 && (
              <Card className="shadow-sm mb-4 border-danger">
                <Card.Header className="bg-danger text-white">
                  <div className="d-flex align-items-center gap-2">
                    <AlertOctagon size={18} />
                    <h6 className="mb-0 fw-semibold">Critical Alerts</h6>
                    <Badge bg="light" text="danger" pill className="ms-auto">
                      {highRiskTasks.length}
                    </Badge>
                  </div>
                </Card.Header>
                <ListGroup variant="flush">
                  {highRiskTasks.slice(0, 3).map((task) => (
                    <ListGroup.Item
                      key={task.id}
                      action
                      onClick={() => navigate(`/task/${task.id}`)}
                      className="py-3"
                    >
                      <div className="d-flex justify-content-between">
                        <div>
                          <div className="d-flex align-items-center gap-2 mb-1">
                            <span>{getCategoryIcon(task.category)}</span>
                            <span className="fw-semibold">{task.title}</span>
                          </div>
                          <div className="d-flex gap-3 small text-muted">
                            <span>Due: {formatDate(task.dueDate)}</span>
                            <span className="text-danger">
                              {getDaysRemaining(task.dueDate)}
                            </span>
                          </div>
                        </div>
                        <Button
                          variant="outline-danger"
                          size="sm"
                          onClick={(e) => {
                            e.stopPropagation();
                            handleViewImpact(task);
                          }}
                        >
                          Impact
                        </Button>
                      </div>
                    </ListGroup.Item>
                  ))}
                </ListGroup>
              </Card>
            )}
          </Col>

          {/* Right Column - Tasks List */}
          <Col lg={8}>
            <Card className="shadow-sm">
              <Card.Header className="bg-white d-flex justify-content-between align-items-center py-3">
                <div>
                  <h5 className="mb-0 fw-semibold">
                    {filterType === "ALL" && "Active Tasks"}
                    {filterType === "TODAY" && "Today's Tasks"}
                    {filterType === "UPCOMING" && "Upcoming Tasks"}
                    {filterType === "OVERDUE" && "Overdue Tasks"}
                    {filterType === "HIGH_RISK" && "High Risk Tasks"}
                    {filterType === "COMPLETED" && "Completed Tasks"}
                  </h5>
                  <small className="text-muted">
                    {filteredTasks.length} tasks found
                  </small>
                </div>
                <Badge bg="primary" pill>
                  {filteredTasks.length}
                </Badge>
              </Card.Header>
              <Card.Body className="p-0">
                {filteredTasks.length > 0 ? (
                  <ListGroup variant="flush">
                    {filteredTasks.map((task) => (
                      <ListGroup.Item
                        key={task.id}
                        action
                        onClick={() => navigate(`/task/${task.id}`)}
                        className="py-3"
                      >
                        <div className="d-flex justify-content-between align-items-start">
                          <div className="flex-grow-1">
                            <div className="d-flex align-items-center gap-2 mb-2">
                              <span className="fs-5">
                                {getCategoryIcon(task.category)}
                              </span>
                              <h6 className="mb-0 fw-semibold">{task.title}</h6>
                              {getRiskBadge(
                                task.riskAnalysis?.riskLevel,
                                task.riskAnalysis?.riskScore,
                              )}
                            </div>
                            {task.description && (
                              <p className="text-muted small mb-2">
                                {task.description.length > 100
                                  ? task.description.substring(0, 100) + "..."
                                  : task.description}
                              </p>
                            )}
                            <div className="d-flex flex-wrap gap-3">
                              <small className="text-muted d-flex align-items-center gap-1">
                                <Calendar size={12} />{" "}
                                {formatDate(task.dueDate)}
                              </small>
                              <small className="text-muted d-flex align-items-center gap-1">
                                <Clock size={12} />{" "}
                                {getDaysRemaining(task.dueDate)}
                              </small>
                              {getPriorityBadge(task.priority)}
                            </div>
                          </div>
                          <div className="text-end ms-3">
                            {task.status !== "COMPLETED" && (
                              <Button
                                variant="success"
                                size="sm"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  setTaskToComplete(task);
                                  setShowCompleteModal(true);
                                }}
                              >
                                <CheckCircle size={14} className="me-1" />{" "}
                                Complete
                              </Button>
                            )}
                            <Button
                              variant="outline-info"
                              size="sm"
                              className="mt-2"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleViewImpact(task);
                              }}
                            >
                              <Eye size={14} className="me-1" /> Impact
                            </Button>
                          </div>
                        </div>
                      </ListGroup.Item>
                    ))}
                  </ListGroup>
                ) : (
                  <div className="text-center py-5">
                    <Clock size={48} className="text-muted mb-3" />
                    <h6 className="text-muted">No tasks in this category</h6>
                    <Button
                      variant="primary"
                      onClick={() => navigate("/create-task")}
                      className="mt-2"
                    >
                      <Plus size={18} className="me-2" /> Create your first task
                    </Button>
                  </div>
                )}
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>

      {/* Modals */}
      <ImpactSimulationModal
        show={showImpactModal}
        onHide={() => setShowImpactModal(false)}
        task={selectedTask}
      />

      <Modal
        show={showCompleteModal}
        onHide={() => setShowCompleteModal(false)}
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title>Complete Task</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <p>Mark "{taskToComplete?.title}" as completed?</p>
          <Form.Group className="mt-3">
            <Form.Label>Upload Proof (Optional)</Form.Label>
            <Form.Control
              type="file"
              onChange={(e) => setCompletionProof(e.target.files[0])}
            />
            <Form.Text className="text-muted">
              Upload screenshot or evidence of completion
            </Form.Text>
          </Form.Group>
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="secondary"
            onClick={() => setShowCompleteModal(false)}
          >
            Cancel
          </Button>
          <Button variant="success" onClick={handleCompleteTask}>
            <CheckCircle className="me-1" /> Complete Task
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Logout Confirmation Modal */}
      <Modal
        show={showLogoutConfirm}
        onHide={() => setShowLogoutConfirm(false)}
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title>Confirm Logout</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <div className="text-center py-3">
            <LogOut size={48} className="text-danger mb-3" />
            <h5>Ready to leave?</h5>
            <p className="text-muted">
              You'll need to log in again to access your tasks and dashboard.
            </p>
          </div>
        </Modal.Body>
        <Modal.Footer>
          <Button
            variant="secondary"
            onClick={() => setShowLogoutConfirm(false)}
          >
            Stay Logged In
          </Button>
          <Button variant="danger" onClick={handleLogout}>
            Logout
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Account Switcher Modal */}
      <Modal
        show={showAccountSwitcher}
        onHide={() => setShowAccountSwitcher(false)}
        centered
        size="lg"
      >
        <Modal.Header closeButton>
          <Modal.Title>Switch Account</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <AccountSwitcher
            accounts={availableAccounts}
            currentAccount={user}
            onSwitch={handleSwitchAccount}
          />
        </Modal.Body>
      </Modal>

      {/* Achievement Modal */}
      <Modal
        show={showAchievementModal}
        onHide={() => setShowAchievementModal(false)}
        centered
        className="achievement-modal"
      >
        <Modal.Body className="text-center py-4">
          <div className="achievement-pop">
            <div className="achievement-badge mb-3">
              <Award size={64} className="text-warning" />
            </div>
            <h4 className="fw-bold text-warning">Achievement Unlocked!</h4>
            <h5 className="mb-3">{newAchievement?.title}</h5>
            <p className="text-muted">{newAchievement?.description}</p>
            <div className="mt-3">
              <Badge bg="success" pill className="px-3 py-2">
                +{newAchievement?.xpReward} XP
              </Badge>
            </div>
          </div>
        </Modal.Body>
        <Modal.Footer className="justify-content-center">
          <Button
            variant="primary"
            onClick={() => setShowAchievementModal(false)}
          >
            Awesome!
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Toast Container for Notifications */}
      <ToastContainer position="bottom-end" className="p-3" />
    </>
  );
};

export default Dashboard;
