// src/context/TaskContext.js
import React, {
  createContext,
  useState,
  useEffect,
  useContext,
  useCallback,
} from "react";
import toast from "react-hot-toast";
import taskService from "../services/taskService";
import { AuthContext } from "./AuthContext";

export const TaskContext = createContext();

export const TaskProvider = ({ children }) => {
  const { user } = useContext(AuthContext);
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [cognitiveLoad, setCognitiveLoad] = useState(null);
  const [failurePredictions, setFailurePredictions] = useState([]);
  const [dashboardData, setDashboardData] = useState(null);

  const loadTasks = useCallback(async () => {
    if (!user) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      const response = await taskService.getTasks();
      // Ensure it's correctly mapped from response.data.tasks or fallback
      const tasksList = response.data.tasks || response.data || [];
      setTasks(tasksList);
      setCognitiveLoad(response.data.cognitiveLoad || null);
    } catch (error) {
      console.error("Error loading tasks:", error);
      toast.error("Failed to load tasks");
    } finally {
      setLoading(false);
    }
  }, [user]);

  const loadFailurePredictions = useCallback(async () => {
    if (!user) return;

    try {
      const response = await taskService.getFailurePredictions();
      setFailurePredictions(response.data || []);
    } catch (error) {
      console.error("Error loading predictions:", error);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      loadTasks();
      loadFailurePredictions();
    } else {
      setTasks([]);
      setLoading(false);
    }
  }, [user, loadTasks, loadFailurePredictions]);

  const createTask = async (taskData) => {
    try {
      const response = await taskService.createTask(taskData);
      const newTask = response.data.task || response.data;
      setTasks((prev) => [newTask, ...prev]);

      toast.success("Task created successfully!");

      return {
        success: true,
        task: newTask,
        needsDecomposition: response.data.needsDecomposition,
        subtasks: newTask.subtasks || [],
      };
    } catch (error) {
      console.error("Error creating task:", error);
      const message = error.response?.data?.message || "Failed to create task";
      toast.error(message);
      return { success: false, error: message };
    }
  };

  const updateTask = async (taskId, updates) => {
    try {
      const response = await taskService.updateTask(taskId, updates);
      const updatedTask = response.data.task || response.data;
      setTasks((prev) =>
        prev.map((task) =>
          task.id === taskId ? { ...task, ...updatedTask } : task,
        ),
      );
      toast.success("Task updated!");
      return updatedTask;
    } catch (error) {
      console.error("Error updating task:", error);
      toast.error("Failed to update task");
      throw error;
    }
  };

  const completeTask = async (taskId, proofFile) => {
    try {
      const response = await taskService.completeTask(taskId, proofFile);
      const completedTask = response.data.task || response.data;
      setTasks((prev) =>
        prev.map((task) =>
          task.id === taskId
            ? {
                ...task,
                status: "COMPLETED",
                completedAt: new Date().toISOString(),
                postAnalysis: completedTask.postAnalysis,
              }
            : task,
        ),
      );
      toast.success("Task completed! 🎉");
      return completedTask;
    } catch (error) {
      console.error("Error completing task:", error);
      toast.error("Failed to complete task");
      throw error;
    }
  };

  const deleteTask = async (taskId) => {
    try {
      await taskService.deleteTask(taskId);
      setTasks((prev) => prev.filter((task) => task.id !== taskId));
      toast.success("Task deleted");
    } catch (error) {
      console.error("Error deleting task:", error);
      toast.error("Failed to delete task");
    }
  };

  const updateSubtask = async (taskId, subtaskId, completed) => {
    try {
      await taskService.updateSubtask(taskId, subtaskId, completed);
      setTasks((prev) =>
        prev.map((task) => {
          if (task.id === taskId && task.subtasks) {
            const updatedSubtasks = task.subtasks.map((sub) =>
              sub.id === subtaskId ? { ...sub, completed } : sub,
            );
            return { ...task, subtasks: updatedSubtasks };
          }
          return task;
        }),
      );
    } catch (error) {
      console.error("Error updating subtask:", error);
    }
  };

  const getTaskById = (taskId) => {
    return tasks.find((task) => task.id === taskId);
  };

  const getActiveTasks = () => {
    return tasks.filter((task) => task.status === "ACTIVE");
  };

  const getHighRiskTasks = () => {
    return tasks.filter(
      (task) =>
        task.riskAnalysis?.riskLevel === "CRITICAL" && task.status === "ACTIVE",
    );
  };

  const getOverdueTasks = () => {
    const now = new Date();
    return tasks.filter(
      (task) =>
        task.status === "ACTIVE" &&
        task.dueDate &&
        new Date(task.dueDate) < now,
    );
  };

  const getCompletedTasks = () => {
    return tasks.filter((task) => task.status === "COMPLETED");
  };

  const getTasksByCategory = (category) => {
    return tasks.filter((task) => task.category === category);
  };

  const getTodayTasks = () => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    return tasks.filter((task) => {
      if (!task.dueDate || task.status !== "ACTIVE") return false;
      const dueDate = new Date(task.dueDate);
      return dueDate >= today && dueDate < tomorrow;
    });
  };

  const getUpcomingTasks = (days = 7) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const futureDate = new Date(today);
    futureDate.setDate(today.getDate() + days);

    return tasks.filter((task) => {
      if (!task.dueDate || task.status !== "ACTIVE") return false;
      const dueDate = new Date(task.dueDate);
      return dueDate >= today && dueDate <= futureDate;
    });
  };

  const stats = {
    active: tasks.filter((t) => t.status === "ACTIVE").length,
    completed: tasks.filter((t) => t.status === "COMPLETED").length,
    overdue: tasks.filter((t) => {
      const now = new Date();
      return t.status === "ACTIVE" && t.dueDate && new Date(t.dueDate) < now;
    }).length,
  };

  return (
    <TaskContext.Provider
      value={{
        tasks,
        stats,
        loading,
        cognitiveLoad,
        failurePredictions,
        dashboardData,
        loadTasks,
        loadFailurePredictions,
        createTask,
        updateTask,
        completeTask,
        deleteTask,
        updateSubtask,
        getTaskById,
        getActiveTasks,
        getHighRiskTasks,
        getOverdueTasks,
        getCompletedTasks,
        getTodayTasks,
        getUpcomingTasks,
        getTasksByCategory,
        setDashboardData,
      }}
    >
      {children}
    </TaskContext.Provider>
  );
};
