// src/services/dashboardService.js
import api from "./api";

const dashboardService = {
  // Get main dashboard summary
  getSummary: () => api.get("/dashboard/summary"),

  // Get analytics data
  getAnalytics: () => api.get("/dashboard/analytics"),

  // Get today's snapshot
  getTodaySnapshot: () => api.get("/dashboard/today"),

  // Get tasks needing attention
  getAttentionTasks: () => api.get("/dashboard/attention"),

  // Get improvement insights
  getImprovementInsights: () => api.get("/dashboard/improvement"),

  // Get recent activity
  getRecentActivity: () => api.get("/dashboard/recent-activity"),

  // Get user stats and achievements
  getUserStats: () => api.get("/dashboard/stats"),

  // Get notifications
  getNotifications: () => api.get("/dashboard/notifications"),

  // Mark notification as read
  markNotificationRead: (id) => api.put(`/dashboard/notifications/${id}/read`),

  // Check achievement
  checkAchievement: (type) => api.post("/dashboard/check-achievement", { type }),

  // Get linked accounts
  getLinkedAccounts: () => api.get("/dashboard/accounts"),

  // Switch account
  switchAccount: (accountId) =>
    api.post("/dashboard/switch-account", { accountId }),
};

export default dashboardService;
